  tables: [
    { id: "c2t1", title: "شعب الدولة وسكانها والأمة", cols: ["وجه المقارنة", "شعب الدولة", "سكان الدولة", "الأمة"], rows: [
      ["المقصود", "الأفراد المتمتعون بجنسية الدولة", "كل مقيم على إقليمها: شعبها والأجانب", "بشر يشتركون في خصائص كالدين واللغة والعرق والتراث"],
      ["الرابطة الجامعة", "الجنسية: انتساب وخضوع وحماية", "الإقامة على إقليم الدولة", "وحدة الدين واللغة والعرق والتراث الحضاري"],
      ["الصلة بحدود الدولة", "يعيشون على إقليمها ويخضعون لنظامها السياسي", "مقيمون على إقليمها", "قد تعيش داخل حدودها السياسية أو خارجها"]
    ], core: "الشعب تجمعه الجنسية، والسكان تجمعهم الإقامة على الإقليم، والأمة تجمعها وحدة الدين واللغة والعرق والتراث وقد تتجاوز حدود الدولة.", pg: "55–56" },
    { id: "c2t2", title: "أنواع الإقليم الثلاثة", cols: ["وجه المقارنة", "الإقليم الأرضي", "الإقليم المائي", "الإقليم الجوي"], rows: [
      ["المقصود", "اليابسة", "المياه الداخلية والبحر الإقليمي", "الفضاء الخارجي الذي يعلو الإقليمين الأرضي والمائي"],
      ["أبرز أحكامه", "حدود طبيعية أو صناعية، ولا يشترط اتصاله ولا مساحته", "حد البحر الإقليمي الأقصى اثنا عشر ميلاً بحرياً", "لا تعبره طائرات أجنبية دون إذن مسبق"],
      ["مثال أو اتفاقية", "خط العرض (38) بين الكوريتين، ونهر الراين", "اتفاقية الأمم المتحدة لقانون البحار", "اتفاقية شيكاغو للطيران المدني والدولي"],
      ["الإشكال", "نزاعات حدودية تُتفادى بترسيم الحدود في معاهدات", "تجاوز بعض الدول الحد أدى أحياناً إلى نزاعات عسكرية", "التقدم التقني يتحدى السيادة المطلقة، ولا آلية دولية بعد"]
    ], core: "الأرضي يابسة بحدود طبيعية أو صناعية، والمائي مياه داخلية وبحر إقليمي حده الأقصى اثنا عشر ميلاً، والجوي فضاء فوقهما لا يُعبر دون إذن.", pg: "57–60" },
    { id: "c2t3", title: "مظهرا السيادة", cols: ["وجه المقارنة", "المظهر الداخلي", "المظهر الخارجي"], rows: [
      ["مجاله", "داخل الدولة", "التعامل مع أشخاص القانون الدولي"],
      ["مضمونه", "أعلى تنظيم داخل الدولة", "الاستقلال السياسي"],
      ["أثره", "تملك الفصل في المنازعات بين الأفراد والوحدات الداخلية", "صناعة القرار لأفراد الدولة لا لعناصر أجنبية"]
    ], core: "الداخلي علوّ الهيئة الحاكمة وفصلها في المنازعات، والخارجي استقلالها السياسي في صناعة القرار؛ وبهما تستقل شخصية الدولة الدولية عن أشخاص الحكام.", pg: "60–61" },
    { id: "c2t4", title: "النظرية المنشئة والنظرية المقررة في الاعتراف", cols: ["وجه المقارنة", "النظرية المنشئة", "النظرية المقررة"], rows: [
      ["كفاية الأركان الثلاثة", "لا تكفي وحدها لاكتساب الشخصية الدولية", "تكفي بمجرد توافرها لاكتساب الشخصية الدولية"],
      ["حكم الاعتراف", "شرط لا بد منه", "ليس شرطاً مسبقاً للانتساب إلى الجماعة الدولية"],
      ["وظيفة الاعتراف", "تحويل وجود الدولة المادي إلى وجود قانوني", "الإقرار بالأمر الواقع وقيام علاقات تعاون دائمة"],
      ["ما يحدد مصير الدولة القانوني", "أعضاء الجماعة الدولية، لملكهم إنشاء القواعد الدولية (بحسب زعمهم)", "توافر أركانها الثلاثة"]
    ], core: "المنشئة تجعل الاعتراف شرطاً يحوّل الوجود المادي إلى قانوني، والمقررة تكتفي بالأركان وتجعله إقراراً بالأمر الواقع؛ والخلاصة أنه فعل إعلاني لا إنشائي.", pg: "63–64" }
  ],
